// Code voor in de Function node
items = items.map(item => {
    const content = item.json.textPlain || item.json.textHtml || '';
    const result = {};

    // Extract all key-value pairs
    const lines = content.split('\n');
    let currentKey = '';
    let currentValue = '';
    let isInDescription = false;
    let descriptionText = [];

    for (let line of lines) {
        line = line.trim();

        // Skip empty lines and [OBJECT] tags
        if (!line || line === '[OBJECT]' || line === '[/OBJECT]') continue;

        // Als we een nieuwe sleutel tegenkomen
        if (line.includes(':')) {
            const [key, ...valueParts] = line.split(':');
            const value = valueParts.join(':').trim();  

            if (key === 'ID' || key === 'ENERGIE_LABEL' || key === 'LAATSTE_UPDATE' || 
                key === 'DATUM_INVOER' || key === 'FUNDA_STATUS' || key === 'LAT' || 
                key === 'LNG' || key.startsWith('FOTO_')) {

                if (isInDescription) {
                    result['beschrijving'] = descriptionText.join('\n').trim();
                    isInDescription = false;
                }

                currentKey = key;
                currentValue = value;

                if (!key.startsWith('FOTO_')) {
                    result[currentKey.toLowerCase()] = currentValue;
                }
            } else if (key === 'BESCHRIJVING') {
                isInDescription = true;
                descriptionText = [value];
            } else if (!isInDescription) {
                if (currentKey) {
                    result[currentKey.toLowerCase()] = currentValue;
                }
                currentKey = key;
                currentValue = value;
            } else {
                descriptionText.push(line);
            }
        } else if (isInDescription) {
            descriptionText.push(line);
        } else if (currentKey) {
            currentValue += ' ' + line;
        }
    }

    if (currentKey && !isInDescription) {
        result[currentKey.toLowerCase()] = currentValue;
    }

    // Extract photos
    const photos = [];
    const photoRegex = /FOTO_\d+:(.*?)(?:\r?\n|$)/g;
    let photoMatch;

    while ((photoMatch = photoRegex.exec(content)) !== null) {
        photos.push(photoMatch[1].trim());
    }
    if (photos.length > 0) {
        result.fotos = JSON.stringify(photos);
    }

    // Clean up specific fields
    if (result.prijs) {
        result.prijs = parseFloat(result.prijs.replace(/[^0-9,]/g, '').replace(',', '.'));
    }

    // Convert numeric fields
    ['woon_opp', 'inhoud', 'perceel', 'kamers', 'slaapkamers', 'badkamers'].forEach(field => {
        if (result[field]) {
            result[field] = parseInt(result[field], 10);
        }
    });

    // Convert coordinates
    if (result.lat) {
        result.lat = parseFloat(result.lat.replace(',', '.'));
    }
    if (result.lng) {
        result.lng = parseFloat(result.lng.replace(',', '.'));
    }

    // Convert dates
    ['laatste_update', 'datum_invoer'].forEach(field => {
        if (result[field]) {
            const [date, time] = result[field].split(' ');
            const [day, month, year] = date.split('-');
            result[field] = `${year}-${month}-${day}T${time}`;
        }
    });

    // Parse lists en converteer naar JSON strings
    ['isolatie', 'tuin', 'tuin_ligging'].forEach(field => {
        if (result[field]) {
            const arrayValue = result[field].split(',').map(item => item.trim());
            result[field] = JSON.stringify(arrayValue);
        }
    });

    // Add lisnr field for database matching
    result.lisnr = result.id;
    delete result.id;  // Remove the original id as we'll use auto-increment in our database

    return {
        json: result
    };
});

return items;

const items = $input.all();

const cleanedItems = items.map(item => {
  let text = item.json.textPlain || '';

  // Eerste grove opschoning
  text = text
    .replace(/\bja\b/gi, 'true')            // "ja" → "true" (optioneel)
    .replace(/\bnee\b/gi, 'false')           // "nee" → "false" (optioneel)
    .replace(/\"\"\"/g, '""')                // triple-quotes oplossen
    .replace(/:\s*(,|\}|\])/g, ': null$1')   // lege waarden als "null"
    .replace(/,\s*]/g, ']')                  // komma voor array einde weg
    .replace(/,\s*}/g, '}')                  // komma voor object einde weg
    .replace(/,\s*$/g, '')                   // trailing komma's verwijderen
    .trim();

  // Geen JSON-parse! Gewoon opslaan als tekst
  return {
    json: {
      cleanedTextPlain: text,
      originalTextPlain: item.json.textPlain || '',
    },
  };
});

return cleanedItems;

// n8n Code node (JavaScript)
let inputText = $input.first().json.cleanedTextPlain;

// Stap 1: Newlines normaliseren
let cleanText = inputText
  .replace(/\\r\\n|\\n|\\r/g, '\n')
  .replace(/\\"/g, '"')
  .trim();

// Stap 2: Extraheer lange tekstvelden VOOR het parsen
// Sla ze op en vervang door een placeholder
const extractedTexts = {};
let placeholderIndex = 0;

// Match string-waarden die newlines of interne quotes bevatten
// Strategie: pak alles tussen ": " en de volgende ",\n  " of "\n  }" patroon
// Specifieker: pak bekende problematische velden op naam
const textFields = ['aanbiedingstekst', 'aanbiedingstekstEngels', 'eigenSiteTekst', 'flyertekst', 'a4Tekst', 'bouwjaartoelichting'];

for (const field of textFields) {
  // Regex: pak de waarde na "fieldname": " tot de volgende opslaanpunt
  // We zoeken het patroon: "field": "...content..." waarbij content alles kan zijn
  const fieldRegex = new RegExp(`("${field}":\\s*)"((?:[^"\\\\]|\\\\.|"(?!\\s*[,}\\]]))*)"`, 's');
  cleanText = cleanText.replace(fieldRegex, (match, prefix, value) => {
    const key = `__PLACEHOLDER_${placeholderIndex}__`;
    extractedTexts[key] = value
      .replace(/\n/g, '\\n')
      .replace(/\r/g, '\\r');
    placeholderIndex++;
    return `${prefix}"${key}"`;
  });
}

// Stap 3: Opschoning van structurele JSON-fouten
cleanText = cleanText.replace(/\s+/g, ' ').trim();
cleanText = cleanText.replace(/,(\s*[}\]])/g, '$1');          // Trailing comma's
cleanText = cleanText.replace(/""+"/g, '""');                  // Dubbele quotes
cleanText = cleanText.replace(/":\s*,/g, '": "",');            // Lege waarden
cleanText = cleanText.replace(/":\s*}/g, '": ""}');            // Key zonder waarde voor }
cleanText = cleanText.replace(/":\s*]/g, '": ""]');            // Key zonder waarde voor ]
cleanText = cleanText.replace(/,(\s*[}\]])/g, '$1');           // Nogmaals trailing comma's

// Encoding fixes
cleanText = cleanText
  .replace(/Â²/g, '²')
  .replace(/Ã©/g, 'é')
  .replace(/Ã /g, 'à')
  .replace(/â¬/g, '€')
  .replace(/â/g, '"')
  .replace(/â/g, '"');

// Stap 4: Parsen
let parsed;
try {
  parsed = JSON.parse(cleanText);
} catch (error) {
  throw new Error(
    'JSON parse mislukt: ' + error.message + 
    '\nSnippet rond fout:\n' + cleanText.slice(0, 800)
  );
}

// Stap 5: Placeholders terugzetten in het geparsede object
function restorePlaceholders(obj) {
  if (typeof obj === 'string') {
    let result = obj;
    for (const [key, value] of Object.entries(extractedTexts)) {
      result = result.replace(key, value);
    }
    return result;
  }
  if (Array.isArray(obj)) return obj.map(restorePlaceholders);
  if (obj !== null && typeof obj === 'object') {
    return Object.fromEntries(
      Object.entries(obj).map(([k, v]) => [k, restorePlaceholders(v)])
    );
  }
  return obj;
}

parsed = restorePlaceholders(parsed);

return [{ json: parsed }];

// Input is al JSON (parsed)

let item = $input.first().json;

// Koopprijs naar getal
if (item.financieel && item.financieel.overdracht) {
  let prijsString = item.financieel.overdracht.koopprijs;

  if (typeof prijsString === 'string' || typeof prijsString === 'number') {
    // Verwijder punten en parse naar integer
    let koopprijs = parseInt(String(prijsString).replace(/\./g, ''), 10) || null;

    item.financieel.overdracht.koopprijs_getal = koopprijs;
  }

  // Optioneel: Koopprijs label maken
  let voorvoegsel = item.financieel.overdracht.koopprijsvoorvoegsel || '';
  if (item.financieel.overdracht.koopprijs_getal !== null) {
    item.financieel.overdracht.koopprijs_label = `${voorvoegsel} €${item.financieel.overdracht.koopprijs_getal.toLocaleString('nl-NL')},-`;
  }
}

return [{ json: item }];

