const expected = $env.N8N_WEBHOOK_SECRET || '';
if (!expected || sent !== expected) {
  throw new Error('Niet geautoriseerd');
}
return $input.all();

const input = $input.first().json || {};
const headers = input.headers || {};
const body = input.body || input;
const payload = body.payload || body.workflowPayload || body;
const raw = body.realworksJson
  || body.originalRealworksJson
  || payload.originalRealworksJson
  || payload.realworksJson
  || payload.cleanedTextPlain
  || body.cleanedTextPlain
  || '';

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('Geen Realworks JSON ontvangen vanuit het platform');
}

let text = raw
  .replace(/\bja\b/gi, 'true')
  .replace(/\bnee\b/gi, 'false')
  .replace(/\"\"\"/g, '\"\"')
  .replace(/:\s*(,|\}|\])/g, ': null$1')
  .replace(/,\s*]/g, ']')
  .replace(/,\s*}/g, '}')
  .replace(/,\s*$/g, '')
  .trim();

return [{
  json: {
    cleanedTextPlain: text,
    originalTextPlain: raw,
    platformProject: body.project || payload.project || null,
    platformPayload: payload,
    headers,
  },
}];
